INSERT INTO pipeline_control.restaurant_review_policy(singleton,version,enabled,operator_id,batch_size,daily_limit) VALUES(true,7,true,'00000000-0000-0000-0000-000000000065',50,50);INSERT INTO pipeline_control.restaurant_review_runs(id,request_id,policy_version,started_at,approved) VALUES('00000000-0000-4000-8000-000000000001',gen_random_uuid(),7,now()-interval '2 days',10);INSERT INTO pipeline_control.restaurant_review_items(run_id,restaurant_id,fingerprint,applied_fingerprint,decision,reason,state,finished_at) VALUES('00000000-0000-4000-8000-000000000001','00000000-0000-0000-0000-000000000068','prior-source',pipeline_control.restaurant_review_fingerprint((SELECT to_jsonb(r) FROM public.restaurants r WHERE id='00000000-0000-0000-0000-000000000068')),'approve','verified','applied',now());DO $test$ DECLARE p jsonb;q jsonb;n int;BEGIN p:=pipeline_control.restaurant_review_manual_preview('00000000-0000-0000-0000-000000000065','run');IF (p->>'remainingApprovals')::int<>49 OR (SELECT sum(value::int) FROM jsonb_each_text(p->'counts'))<>1 THEN RAISE EXCEPTION 'REVIEW_FIX_APPLIED_EXCLUSION_OR_BUDGET';END IF; q:=pipeline_control.restaurant_review_manual_preview('00000000-0000-0000-0000-000000000065','stop');IF q->'counts'<>'{}' OR q->>'version'<>'7' THEN RAISE EXCEPTION 'REVIEW_FIX_STOP';END IF;UPDATE pipeline_control.restaurant_review_items SET state='succeeded',reason='daily_limit';p:=pipeline_control.restaurant_review_manual_preview('00000000-0000-0000-0000-000000000065','run');IF (SELECT sum(value::int) FROM jsonb_each_text(p->'counts'))<>2 THEN RAISE EXCEPTION 'REVIEW_FIX_DEFERRED_INCLUDE';END IF;UPDATE pipeline_control.restaurant_review_runs SET policy_version=6;p:=pipeline_control.restaurant_review_manual_preview('00000000-0000-0000-0000-000000000065','run');IF (SELECT sum(value::int) FROM jsonb_each_text(p->'counts'))<>1 THEN RAISE EXCEPTION 'REVIEW_FIX_STALE_POLICY';END IF;END $test$;ROLLBACK;